-- Run transactionally through scripts/verify-moderation-schema.ts. Always rollback.
create temporary table mod_ids as select gen_random_uuid() owner,gen_random_uuid() question,gen_random_uuid() reply,gen_random_uuid() result;
create temporary table mod_assertions(name text primary key,passed boolean not null check(passed));
grant select on mod_ids to authenticated;
grant select,insert on mod_assertions to authenticated;
insert into auth.users(id,email,email_confirmed_at) select owner,owner::text||'@example.invalid',now() from mod_ids;
insert into private.pilot_emails(email) select owner::text||'@example.invalid' from mod_ids;
insert into public.profiles(id,display_name) select owner,'Synthetic member' from mod_ids;
insert into public.questions(id,owner_id,request_id,title,body) select question,owner,gen_random_uuid(),'Synthetic moderation visibility question','Original question text' from mod_ids;
insert into public.write_receipts(owner_id,request_id,fingerprint,result) select owner,question,'fixture-fingerprint',jsonb_build_object('id',question,'title','Synthetic moderation visibility question') from mod_ids;
insert into public.replies(id,question_id,owner_id,request_id,body) select reply,question,owner,gen_random_uuid(),'Original reply text' from mod_ids;
insert into public.test_results(id,question_id,reply_id,owner_id,request_id,outcome,environment,evidence) select result,question,reply,owner,gen_random_uuid(),'passed','SQL test','Original evidence' from mod_ids;
update public.questions set status='solved',accepted_reply_id=(select reply from mod_ids) where id=(select question from mod_ids);
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',owner,'role','authenticated')::text,true) from mod_ids;
insert into mod_assertions select 'Member can read visible question',exists(select 1 from public.questions where id=(select question from mod_ids));
do $$ begin
 begin perform * from private.staff_roles; raise exception 'Staff role read accepted'; exception when insufficient_privilege then insert into mod_assertions values('Staff roles private',true); end;
 begin perform * from private.content_reports; raise exception 'Report read accepted'; exception when insufficient_privilege then insert into mod_assertions values('Reports private',true); end;
 begin perform * from private.applications; raise exception 'Application read accepted'; exception when insufficient_privilege then insert into mod_assertions values('Applications private',true); end;
 begin update private.staff_audit set reason='Forged audit rewrite'; raise exception 'Audit update accepted'; exception when insufficient_privilege then insert into mod_assertions values('Audit rewrite denied',true); end;
 begin delete from private.staff_audit; raise exception 'Audit delete accepted'; exception when insufficient_privilege then insert into mod_assertions values('Audit deletion denied',true); end;
 begin insert into private.staff_roles(owner_id,role) select owner,'master' from mod_ids; raise exception 'Self promotion accepted'; exception when insufficient_privilege then insert into mod_assertions values('Self promotion denied',true); end;
 begin update public.questions set moderation_hidden=true where id=(select question from mod_ids); raise exception 'Hide accepted'; exception when insufficient_privilege then insert into mod_assertions values('Ordinary hide denied',true); end;
 begin insert into public.questions(owner_id,request_id,title,body,moderation_hidden) select owner,gen_random_uuid(),'Forged hidden field','text',true from mod_ids; raise exception 'Hidden insert accepted'; exception when insufficient_privilege then insert into mod_assertions values('Hidden insert denied',true); end;
end $$;
reset role;
update public.replies set moderation_hidden=true where id=(select reply from mod_ids);
set local role authenticated;
insert into mod_assertions select 'Hidden reply denied',not exists(select 1 from public.replies where id=(select reply from mod_ids));
insert into mod_assertions select 'Hidden reply evidence denied',not exists(select 1 from public.test_results where id=(select result from mod_ids));
reset role;
update public.replies set moderation_hidden=false where id=(select reply from mod_ids);
update public.questions set moderation_hidden=true where id=(select question from mod_ids);
set local role authenticated;
insert into mod_assertions select 'Hidden parent denies question',not exists(select 1 from public.questions where id=(select question from mod_ids));
insert into mod_assertions select 'Hidden parent denies reply',not exists(select 1 from public.replies where id=(select reply from mod_ids));
insert into mod_assertions select 'Hidden parent denies evidence',not exists(select 1 from public.test_results where id=(select result from mod_ids));
insert into mod_assertions select 'Hidden question receipt denies title',not exists(select 1 from public.write_receipts where request_id=(select question from mod_ids));
reset role;
update public.questions set moderation_hidden=false where id=(select question from mod_ids);
insert into private.account_restrictions(owner_id,kind,until_at,reason) select owner,'suspend',now()+interval '1 day','Synthetic temporary restriction' from mod_ids;
set local role authenticated;
insert into mod_assertions select 'Restricted membership denied',not private.is_member();
insert into mod_assertions select 'Restricted raw data denied',not exists(select 1 from public.questions where id=(select question from mod_ids));
reset role;
update private.account_restrictions set until_at=now()-interval '1 second' where owner_id=(select owner from mod_ids);
set local role authenticated;
insert into mod_assertions select 'Expired restriction restores membership',private.is_member();
reset role;
insert into mod_assertions select 'Original evidence preserved',evidence='Original evidence' from public.test_results where id=(select result from mod_ids);
insert into mod_assertions select 'Historical resolution reference preserved',status='solved' and accepted_reply_id=(select reply from mod_ids) from public.questions where id=(select question from mod_ids);
